    assert db.execute('SELECT done FROM progress WHERE lesson_id = ?', ('loops',)).fetchone() == (1,)
    print('PASS: valid relation')
    try:
        add_progress(db, 'missing', 1)
    except sqlite3.IntegrityError:
        pass
    else:
        raise AssertionError('orphan must be rejected')
