        db.execute('DELETE FROM lesson WHERE id = ?', ('loops',))
    except sqlite3.IntegrityError:
        pass
    else:
        raise AssertionError('referenced parent deletion must be rejected')
    print('PASS: orphan and delete policy')
finally:
    db.close()
